package com.example.reporting

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import org.thymeleaf.TemplateEngine
import org.thymeleaf.context.Context
import org.thymeleaf.templateresolver.StringTemplateResolver

fun createTemplateEngine(): TemplateEngine {
    val engine = TemplateEngine()
    val resolver = StringTemplateResolver()
    resolver.templateMode = org.thymeleaf.templatemode.TemplateMode.HTML
    engine.setTemplateResolver(resolver)
    return engine
}

val templateEngine = createTemplateEngine()

fun renderReport(userName: String, reportData: String, customHeader: String): String {
    // Build the template with user-provided header for branding
    val template = """
        <!DOCTYPE html>
        <html>
        <head><title>Report</title></head>
        <body>
            <div class="header">$customHeader</div>
            <h1>Report for <span th:text="${'$'}{userName}">User</span></h1>
            <div class="content">
                <p th:text="${'$'}{reportData}">Data placeholder</p>
            </div>
            <footer>
                <p>Generated by ReportService v2.4.1</p>
            </footer>
        </body>
        </html>
    """.trimIndent()

    val context = Context()
    context.setVariable("userName", userName)
    context.setVariable("reportData", reportData)
    return templateEngine.process(template, context)
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v1/reports/generate") {
                val params = call.receiveParameters()
                val userName = params["user_name"] ?: "Anonymous"
                val reportData = params["report_data"] ?: "No data"
                val customHeader = params["custom_header"] ?: "<h2>Standard Report</h2>"

                // Validate userName length
                if (userName.length > 100) {
                    call.respond(HttpStatusCode.BadRequest, "Username too long")
                    return@post
                }

                // Basic XSS filter on reportData (not relevant to SSTI)
                val sanitizedData = reportData.replace("<script", "&lt;script")

                try {
                    val html = renderReport(userName, sanitizedData, customHeader)
                    call.respondText(html, ContentType.Text.Html)
                } catch (e: Exception) {
                    call.respond(HttpStatusCode.InternalServerError, "Template rendering failed: ${e.message}")
                }
            }

            get("/health") {
                call.respondText("OK", ContentType.Text.Plain)
            }

            get("/api/v1/reports/templates") {
                // List available report templates from filesystem
                val templateDir = java.io.File("/app/templates")
                val files = templateDir.listFiles()?.map { it.name } ?: emptyList()
                call.respondText(files.joinToString("\n"), ContentType.Text.Plain)
            }
        }
    }.start(wait = true)
}
